using System.Net;
using System.Net.Http.Json;
using BuildingFlow.Application;
using BuildingFlow.Domain;
using Microsoft.EntityFrameworkCore;
using Xunit;
namespace BuildingFlow.IntegrationTests;
public sealed class ReportApiTests(SiteApiTests.SiteApiFactory factory):IClassFixture<SiteApiTests.SiteApiFactory>
{
    private async Task<(Property P,string Actor)> Seed(){var actor=Guid.NewGuid().ToString();var p=new Property("Report "+actor,"City","District","Address",PropertyType.APARTMENT);await factory.WithDb(async db=>{db.Add(p);db.Add(new PropertyMembership(p.Id,actor));await db.SaveChangesAsync();});return(p,actor);}
    private static string Root(Guid p)=>$"/api/v1/properties/{p}/reports?period=";
    [PostgresTheory][InlineData("SUPER_ADMIN")][InlineData("SITE_ADMIN")][InlineData("MANAGER")][InlineData("ACCOUNTANT")]
    public async Task EmptyReportIsScopedAndZeroWithoutInventedConsumption(string role){var x=await Seed();using var c=TestToken.Client(factory,x.Actor,role);var r=(await c.GetFromJsonAsync<ManagementReport>(Root(x.P.Id)+"2026-09"))!;Assert.Equal(x.P.Id,r.PropertyId);Assert.Equal(0,r.UnitCount);Assert.Equal("0.00",r.ReceiptsAmount);Assert.Equal(3,r.Consumption.Count);Assert.All(r.Consumption,v=>{Assert.Equal("0.000",v.Consumption);Assert.Equal(0,v.ReadingCount);});}
    [PostgresFact] public async Task ReportSeparatesOccupancyMonthlyChargesCashAndWindowedConsumptionWithoutNames()
    {
        var x=await Seed();await factory.WithDb(async db=>{var p=await db.Properties.Include(p=>p.Units).SingleAsync(p=>p.Id==x.P.Id);var u=p.AddUnit("1",0,80);var vacant=p.AddUnit("2",1,90);var disabled=p.AddUnit("3",2,70);disabled.SetEnabled(false);var person=new Person(p.Id,"SECRET_NAME","SECRET_SURNAME");db.Add(person);db.Add(new UnitOccupancy(p.Id,u.Id,person.Id,OccupancyType.TENANT,new(2026,8,1),new(2026,9,30)));db.Add(new UnitOccupancy(p.Id,u.Id,person.Id,OccupancyType.RESIDENT,new(2026,8,1)));db.Add(new UnitOccupancy(p.Id,vacant.Id,person.Id,OccupancyType.OWNER,new(2026,8,1)));var assessment=new DuesAssessment(p.Id,Guid.NewGuid(),new string('a',64),new(2026,9,1),100,"TRY",new(2026,9,10),"Dues");var charge=assessment.AddCharge(u.Id);db.Add(assessment);var payment=new Payment(p.Id,u.Id,Guid.NewGuid(),new string('a',64),25,"TRY",new(2026,10,1),PaymentMethod.CASH,null,"Cash in another month");payment.Allocate(charge,25);payment.ValidateComplete();db.Add(payment);var expense=new Expense(p.Id,Guid.NewGuid(),new string('a',64),ExpenseCategory.ENERGY,12.35m,new(2026,9,15),"Energy",null);db.Add(expense);var cancelled=new Expense(p.Id,Guid.NewGuid(),new string('a',64),ExpenseCategory.OTHER,1000,new(2026,9,15),"Wrong",null);cancelled.Cancel("Wrong",DateTimeOffset.UtcNow);db.Add(cancelled);await db.SaveChangesAsync();var meter=new Meter(p.Id,null,Guid.NewGuid(),new string('a',64),"Water",MeterKind.WATER);db.Add(meter);var before=new MeterReading(p.Id,meter.Id,new(2026,8,31));db.Add(before);db.Add(before.Revise(Guid.NewGuid(),new string('a',64),100,"Baseline"));var current=new MeterReading(p.Id,meter.Id,new(2026,9,15));db.Add(current);db.Add(current.Revise(Guid.NewGuid(),new string('a',64),112.345m,"Monthly"));await db.SaveChangesAsync();});
        using var c=TestToken.Client(factory,x.Actor,"ACCOUNTANT");var response=await c.GetAsync(Root(x.P.Id)+"2026-09");Assert.Equal(HttpStatusCode.OK,response.StatusCode);var text=await response.Content.ReadAsStringAsync();Assert.DoesNotContain("SECRET",text);Assert.DoesNotContain("personId",text);var r=(await response.Content.ReadFromJsonAsync<ManagementReport>())!;Assert.Equal(3,r.UnitCount);Assert.Equal(2,r.ActiveUnitCount);Assert.Equal(1,r.OccupiedUnitCount);Assert.Equal(1,r.VacantUnitCount);Assert.Equal("100.00",r.AssessedAmount);Assert.Equal("75.00",r.OutstandingAmount);Assert.Equal("0.00",r.ReceiptsAmount);Assert.Equal("12.35",r.ExpensesAmount);Assert.Equal("12.345",r.Consumption.Single(v=>v.Kind=="WATER").Consumption);var october=(await c.GetFromJsonAsync<ManagementReport>(Root(x.P.Id)+"2026-10"))!;Assert.Equal("25.00",october.ReceiptsAmount);Assert.Equal("0.00",october.AssessedAmount);
    }
    [PostgresFact] public async Task ReportRejectsUnscopedRolesMalformedJwtDeletedParentAndBadPeriod(){var x=await Seed();using var anon=factory.CreateClient();using var resident=TestToken.Client(factory,x.Actor,"RESIDENT");using var outsider=TestToken.Client(factory,Guid.NewGuid().ToString(),"ACCOUNTANT");using var admin=TestToken.Client(factory,x.Actor,"SUPER_ADMIN");Assert.Equal(HttpStatusCode.Unauthorized,(await anon.GetAsync(Root(x.P.Id)+"2026-09")).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await resident.GetAsync(Root(x.P.Id)+"2026-09")).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await outsider.GetAsync(Root(x.P.Id)+"2026-09")).StatusCode);foreach(var period in new[]{"1999-01","9999-01","2026-13","private"})Assert.Equal(HttpStatusCode.BadRequest,(await admin.GetAsync(Root(x.P.Id)+period)).StatusCode);await factory.WithDb(async db=>{db.Remove(await db.Properties.SingleAsync(p=>p.Id==x.P.Id));await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.NotFound,(await admin.GetAsync(Root(x.P.Id)+"2026-09")).StatusCode);}
}
